const KHATMA_PLANS={"ashr-10":{name:"ختمة العشر",days:10,juzPerDay:3,desc:"3 أجزاء يومياً — تختم في العشر"},monthly:{name:"ختمة شهرية",days:30,juzPerDay:1,desc:"جزء واحد يومياً"},"two-month":{name:"ختمة الشهرين",days:60,juzPerDay:.5,desc:"نصف جزء يومياً — للمبتدئين"},weekly:{name:"ختمة أسبوعية",days:7,juzPerDay:4.3,desc:"للحُفّاظ — ختمة كل أسبوع"}};function getActiveKhatmaPlan(){return localStorage.getItem("zad_khatma_plan")||"ashr-10"}function setKhatmaPlan(a){localStorage.setItem("zad_khatma_plan",a),renderKhatmaPlans(),"function"==typeof showToast&&showToast(`✅ ${KHATMA_PLANS[a].name}`)}function renderKhatmaPlans(){const a=document.getElementById("khatma-plans");if(!a)return;const n=getActiveKhatmaPlan();a.innerHTML=Object.entries(KHATMA_PLANS).map(([a,e])=>`\n    <div class="khatma-plan-card ${a===n?"active":""}" onclick="setKhatmaPlan('${a}')">\n      <div class="kp-name">${e.name}</div>\n      <div class="kp-desc">${e.desc}</div>\n      <div class="kp-days">${e.days} يوم</div>\n    </div>\n  `).join("")}window.setKhatmaPlan=setKhatmaPlan;const SURAHS_SHORT=[{n:114,name:"الناس",ayat:6},{n:113,name:"الفلق",ayat:5},{n:112,name:"الإخلاص",ayat:4},{n:111,name:"المسد",ayat:5},{n:110,name:"النصر",ayat:3},{n:109,name:"الكافرون",ayat:6},{n:108,name:"الكوثر",ayat:3},{n:107,name:"الماعون",ayat:7},{n:106,name:"قريش",ayat:4},{n:105,name:"الفيل",ayat:5}];async function getHifzProgress(){try{return await(window.ZadStore?.getState("hifzProgress",{}))||{}}catch{return{}}}async function toggleHifz(a){const n=await getHifzProgress();n[a]?delete n[a]:n[a]={masteredAt:Date.now(),reviewCount:0},await(window.ZadStore?.setState("hifzProgress",n)),renderHifzTracker()}async function renderHifzTracker(){const a=document.getElementById("hifz-tracker");if(!a)return;const n=await getHifzProgress(),e=Object.keys(n).length;a.innerHTML=`\n    <div class="hifz-stats">\n      <div class="hifz-stat-num">${e}</div>\n      <div class="hifz-stat-lbl" data-zad-ui><span>سورة محفوظة من</span> ${SURAHS_SHORT.length} <span>(جزء عمّ)</span></div>\n    </div>\n    <div class="hifz-grid">\n      ${SURAHS_SHORT.map(a=>`\n        <div class="hifz-surah ${n[a.n]?"memorized":""}" onclick="toggleHifz(${a.n})">\n          <span class="hifz-surah-name">${a.name}</span>\n          <span class="hifz-surah-ayat" data-zad-ui>${a.ayat} <span>آيات</span></span>\n          ${n[a.n]?'<span class="hifz-check">✓</span>':""}\n        </div>\n      `).join("")}\n    </div>`}window.toggleHifz=toggleHifz;const QURAN_APIS={primary:{name:"Quran.com API",base:"https://api.quran.com/api/v4",features:["نص عثماني","تفسير (ابن كثير، السعدي، الطبري)","تلاوة","ترجمة 40+ لغة"],needsKey:!1},fallback:{name:"AlQuran.cloud",base:"https://api.alquran.cloud/v1",features:["نص","تلاوة","بسيط بدون مفتاح"],needsKey:!1}};async function fetchVerse(a,n){try{const e=`${QURAN_APIS.primary.base}/verses/by_key/${a}:${n}?fields=text_uthmani&translations=131`,t=await fetch(e);if(t.ok){const a=await t.json();return{text:a.verse?.text_uthmani,translation:a.verse?.translations?.[0]?.text,source:"Quran.com"}}throw new Error("primary failed")}catch{try{const e=`${QURAN_APIS.fallback.base}/ayah/${a}:${n}/quran-uthmani`,t=await fetch(e),r=await t.json();return{text:r.data?.text,translation:null,source:"AlQuran.cloud"}}catch{return null}}}window.fetchVerse=fetchVerse;const QURAN_CSS="\n#khatma-plans { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }\n.khatma-plan-card { padding: 16px; border-radius: 14px; border: 2px solid var(--border, #ddd);\n  background: var(--sand, #faf9f6); cursor: pointer; transition: all .2s; text-align: center; }\n.khatma-plan-card.active { border-color: var(--zad-green-900, #0e3b2e); background: rgba(14,59,46,.06); }\n.kp-name { font-weight: 800; font-size: 15px; margin-bottom: 4px; }\n.kp-desc { font-size: 12px; color: var(--muted, #888); margin-bottom: 8px; line-height: 1.5; }\n.kp-days { font-size: 13px; font-weight: 700; color: var(--green-mid, #1a5d47); }\n.hifz-stats { text-align: center; margin-bottom: 20px; }\n.hifz-stat-num { font-size: 42px; font-weight: 900; color: var(--green-deep, #0e3b2e); }\n.hifz-stat-lbl { font-size: 13px; color: var(--muted, #888); }\n.hifz-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); gap: 8px; }\n.hifz-surah { position: relative; padding: 12px 8px; border-radius: 10px; border: 1.5px solid var(--border, #ddd);\n  background: var(--sand, #faf9f6); cursor: pointer; text-align: center; transition: all .2s; }\n.hifz-surah.memorized { background: rgba(14,59,46,.1); border-color: var(--zad-green-700, #1a5d47); }\n.hifz-surah-name { display: block; font-weight: 700; font-size: 14px; }\n.hifz-surah-ayat { display: block; font-size: 11px; color: var(--muted, #888); margin-top: 2px; }\n.hifz-check { position: absolute; top: 4px; left: 4px; color: var(--green-mid, #1a5d47); font-weight: 900; }\n";function injectQuranCSS(){if(document.getElementById("quran-module-css"))return;const a=document.createElement("style");a.id="quran-module-css",a.textContent=QURAN_CSS,document.head.appendChild(a)}document.addEventListener("DOMContentLoaded",()=>{(document.getElementById("khatma-plans")||document.getElementById("hifz-tracker"))&&(injectQuranCSS(),renderKhatmaPlans(),renderHifzTracker(),console.log("[QuranModule] ✅ موديول القرآن جاهز"))}),window.KHATMA_PLANS=KHATMA_PLANS,window.QURAN_APIS=QURAN_APIS;